import{_ as e,C as a,o as n,c as s,aj as d,E as o}from"./framework.js";const m=JSON.parse('{"title":"市场 | Product | Documentation","description":"市场 in Kooboo: 市场用于“先选一个可用起点，再创建站点”。模板被使用后会生成普通 Kooboo 站点，后续页面、内容、样式、脚本仍回到站点后台维护。","frontmatter":{"title":"市场 | Product | Documentation","description":"市场 in Kooboo: 市场用于“先选一个可用起点，再创建站点”。模板被使用后会生成普通 Kooboo 站点，后续页面、内容、样式、脚本仍回到站点后台维护。","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/zh/product/market.html"}]]},"headers":[],"relativePath":"zh/product/market.md","filePath":"product/market.md","lastUpdated":1781002819000}'),h={name:"zh/product/market.md"};function g(l,t,i,b,c,p){const r=a("DocImage");return n(),s("div",null,[t[0]||(t[0]=d('<h1 id="市场" tabindex="-1">市场 <a class="header-anchor" href="#市场" aria-label="Permalink to &quot;市场&quot;">​</a></h1><blockquote><p>从模板市场选择站点起点，查看模板详情，或管理自己分享的模板。</p></blockquote><h2 id="如何打开" tabindex="-1">如何打开 <a class="header-anchor" href="#如何打开" aria-label="Permalink to &quot;如何打开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>说明</th></tr></thead><tbody><tr><td>顶部入口</td><td>点击顶部导航的 <strong>市场</strong> 图标</td></tr><tr><td>模板列表</td><td><code>/_Admin/templates</code></td></tr><tr><td>模板详情</td><td><code>/_Admin/template/detail?templateId={模板Id}</code></td></tr><tr><td>我的分享</td><td><code>/_Admin/template/my-shared</code></td></tr><tr><td>页面层级</td><td>账户级页面，通常不带 <code>SiteId</code></td></tr></tbody></table><p>市场用于“先选一个可用起点，再创建站点”。模板被使用后会生成普通 Kooboo 站点，后续页面、内容、样式、脚本仍回到站点后台维护。</p>',5)),o(r,{src:"/product/market/templates-overview.png",alt:"市场模板列表：搜索、分类、主题和颜色筛选",width:"1120"}),t[1]||(t[1]=d('<h2 id="模板列表" tabindex="-1">模板列表 <a class="header-anchor" href="#模板列表" aria-label="Permalink to &quot;模板列表&quot;">​</a></h2><p>进入市场后，顶部工具栏从左到右依次是：</p><table tabindex="0"><thead><tr><th>控件</th><th>用法</th></tr></thead><tbody><tr><td><strong>模板名称</strong> 搜索框</td><td>输入关键字后自动搜索。前端会去掉空格再提交查询，适合按模板名快速过滤</td></tr><tr><td>类型下拉框</td><td>来自模板类型接口；切换后刷新列表</td></tr><tr><td><strong>主题</strong> 下拉框</td><td>仅在类型为全部或站点模板时显示，多选后会在列表上方生成筛选标签</td></tr><tr><td><strong>颜色</strong> 下拉框</td><td>仅在类型为全部或站点模板时显示，多选颜色后刷新列表</td></tr><tr><td><strong>我分享的</strong></td><td>打开自己的模板分享列表</td></tr></tbody></table><p>列表主体按卡片展示模板。卡片显示模板封面、模板名和下载次数；点击卡片进入模板详情。筛选后，列表上方会显示已选主题或颜色，点击标签右侧关闭图标可移除单个条件，点击 <strong>清除全部</strong> 可重置筛选。</p><p>如果没有匹配模板，页面会显示空状态。此时先清除筛选条件，或换一个更短的关键字再试。</p><h2 id="查看模板详情并创建站点" tabindex="-1">查看模板详情并创建站点 <a class="header-anchor" href="#查看模板详情并创建站点" aria-label="Permalink to &quot;查看模板详情并创建站点&quot;">​</a></h2><p>点击模板卡片进入详情页。详情页顶部同时承担“预览模板”和“用模板创建站点”的操作。</p>',7)),o(r,{src:"/product/market/template-detail.png",alt:"模板详情：站点名称、域名选择、创建按钮与模板预览",width:"1120"}),t[2]||(t[2]=d('<table tabindex="0"><thead><tr><th>区域</th><th>填写或检查什么</th></tr></thead><tbody><tr><td>返回按钮</td><td>回到模板列表，并保留从站点文件夹进入市场时的 <code>currentFolder</code> 查询参数</td></tr><tr><td><strong>站点名</strong></td><td>新站点的后台名称；必填，长度 1-50，只能使用简单名称规则，且不能与已有站点重名</td></tr><tr><td><strong>域名</strong> 输入框</td><td>新站点的子域名前缀；必填，长度 1-63，需要满足子域名格式并且域名绑定不能重复</td></tr><tr><td>根域名下拉框</td><td>选择当前账户可用的根域名；有些根域名使用 <code>-root</code> 形式，有些使用 <code>.root</code> 形式，以界面显示为准</td></tr><tr><td><strong>创建</strong></td><td>校验通过后调用模板创建站点；如果从站点文件夹进入市场，创建后会把新站点放回该文件夹</td></tr></tbody></table><p>详情页中部是预览区。部分模板直接展示截图；如果模板提供在线预览，则会以 iframe 展示，并可在桌面、平板、手机尺寸之间切换。预览下方展示作者、分类、大小、下载次数、最后修改时间，以及模板包含的布局、菜单、页面、视图、图片、内容数量。</p><p>创建完成后页面会回到站点列表。接下来通常点击新站点的 <strong>管理</strong>，进入 <code>/_Admin/site?SiteId={站点GUID}</code> 继续改页面、内容和设置。</p><h2 id="我的分享" tabindex="-1">我的分享 <a class="header-anchor" href="#我的分享" aria-label="Permalink to &quot;我的分享&quot;">​</a></h2><p>在模板列表点击 <strong>我分享的</strong>，进入自己的模板管理页。</p>',5)),o(r,{src:"/product/market/my-shared.png",alt:"我的分享：已分享模板列表与分享按钮",width:"1120"}),t[3]||(t[3]=d('<table tabindex="0"><thead><tr><th>操作</th><th>说明</th></tr></thead><tbody><tr><td><strong>分享</strong></td><td>打开分享模板弹窗，新增一个分享模板</td></tr><tr><td>模板卡片预览</td><td>点击眼睛图标打开模板预览地址</td></tr><tr><td><strong>编辑</strong></td><td>修改模板名称、价格、封面、截图，也可以补充中文名称、中文封面和中文截图</td></tr><tr><td><strong>更新</strong></td><td>更新模板包本身；可从现有 Kooboo 站点重新生成，也可以上传 ZIP 包</td></tr><tr><td>更多操作 → <strong>删除</strong></td><td>删除自己分享的模板；删除前会弹确认</td></tr></tbody></table><p>如果列表为空，说明当前账号还没有分享模板。先点击 <strong>分享</strong> 新建，或切换到拥有模板的账号再查看。</p><h2 id="分享模板" tabindex="-1">分享模板 <a class="header-anchor" href="#分享模板" aria-label="Permalink to &quot;分享模板&quot;">​</a></h2><p>分享弹窗分为“新增分享”和“更新模板包”两种状态：在 <strong>我的分享</strong> 页点击 <strong>分享</strong> 是新增；在某个模板卡片上点击 <strong>更新</strong> 是更新包。</p>',4)),o(r,{src:"/product/market/share-template-dialog.png",alt:"分享模板弹窗：模板名称、分享方式、站点或 ZIP 包、封面截图",width:"1120"}),t[4]||(t[4]=d('<p>新增分享时需要填写：</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>模板名称</strong></td><td>市场中展示的名称；必填</td></tr><tr><td><strong>分类</strong></td><td>从模板类型下拉框选择</td></tr><tr><td><strong>价格</strong></td><td>当前界面以 <code>CNY</code> 展示；不收费可填 <code>0</code></td></tr><tr><td><strong>分享方式</strong></td><td>选择 <strong>从 Kooboo 中选择</strong> 或 <strong>上传 ZIP</strong></td></tr><tr><td><strong>站点</strong></td><td>分享方式为 Kooboo 站点时必选；选择后会自动读取站点封面作为封面和截图初始值</td></tr><tr><td><strong>文件</strong></td><td>分享方式为 ZIP 时上传 <code>.zip</code> 包</td></tr><tr><td><strong>封面 / 截图</strong></td><td>可保留自动生成图，也可悬停图片后点击更换</td></tr><tr><td><strong>添加中文</strong></td><td>补充中文模板名称、中文封面和中文截图，用于中文市场展示</td></tr></tbody></table><p>更新模板包时，弹窗标题为“更新模板包”，只处理模板内容来源：选择 Kooboo 站点或上传 ZIP 包。模板名称、价格、封面、截图等展示信息请用 <strong>编辑</strong> 操作维护。</p><h2 id="编辑模板信息" tabindex="-1">编辑模板信息 <a class="header-anchor" href="#编辑模板信息" aria-label="Permalink to &quot;编辑模板信息&quot;">​</a></h2><p>在模板卡片上点击 <strong>编辑</strong>，可以维护模板展示信息。</p><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>模板名称</strong></td><td>市场列表和详情页展示的名称；必填</td></tr><tr><td><strong>价格</strong></td><td>模板价格，当前界面显示为 <code>CNY</code></td></tr><tr><td><strong>封面</strong></td><td>模板卡片使用的缩略图</td></tr><tr><td><strong>截图</strong></td><td>模板详情页可能展示的长截图</td></tr><tr><td><strong>添加中文</strong></td><td>补充中文名称、中文封面、中文截图；启用后中文名称必填</td></tr></tbody></table><h2 id="什么时候用市场" tabindex="-1">什么时候用市场 <a class="header-anchor" href="#什么时候用市场" aria-label="Permalink to &quot;什么时候用市场&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>建议</th></tr></thead><tbody><tr><td>想快速体验 Kooboo</td><td>先从模板创建站点，再按 <a href="/kb-docs/zh/quick-start/">快速开始</a> 调整</td></tr><tr><td>想复用行业页面结构</td><td>选择接近业务的模板，进入站点后改页面、内容、样式和脚本</td></tr><tr><td>想沉淀团队模板</td><td>将成熟站点整理好封面、截图和示例内容，再分享到市场</td></tr><tr><td>想更新已发布模板</td><td>在 <strong>我的分享</strong> 中用 <strong>更新</strong> 替换模板包，用 <strong>编辑</strong> 调整展示信息</td></tr></tbody></table><h2 id="与-cms-的关系" tabindex="-1">与 CMS 的关系 <a class="header-anchor" href="#与-cms-的关系" aria-label="Permalink to &quot;与 CMS 的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>市场做什么</th><th>CMS 做什么</th></tr></thead><tbody><tr><td>选择模板、预览模板、创建新站点</td><td>维护新站点的页面、内容、菜单、样式、脚本</td></tr><tr><td>分享一个站点或 ZIP 包为模板</td><td>在分享前清理测试数据、整理页面和媒体资源</td></tr><tr><td>维护模板封面、截图、价格和多语言展示</td><td>继续在站点后台维护实际业务功能</td></tr></tbody></table><h2 id="典型工作流" tabindex="-1">典型工作流 <a class="header-anchor" href="#典型工作流" aria-label="Permalink to &quot;典型工作流&quot;">​</a></h2><table tabindex="0"><thead><tr><th>目标</th><th>操作</th></tr></thead><tbody><tr><td>用模板创建站点</td><td>市场 → 搜索或筛选模板 → 打开详情 → 填站点名、子域名、根域名 → <strong>创建</strong></td></tr><tr><td>分享现有站点</td><td>先在 CMS 清理测试内容 → 市场 → <strong>我分享的</strong> → <strong>分享</strong> → 选择站点 → 检查封面和截图 → <strong>分享</strong></td></tr><tr><td>更新模板包</td><td><strong>我分享的</strong> → 模板卡片 <strong>更新</strong> → 选择站点或上传 ZIP → 确认</td></tr><tr><td>优化模板展示</td><td><strong>我分享的</strong> → 模板卡片 <strong>编辑</strong> → 调整名称、价格、封面、截图和中文资料</td></tr></tbody></table><h2 id="相关" tabindex="-1">相关 <a class="header-anchor" href="#相关" aria-label="Permalink to &quot;相关&quot;">​</a></h2><table tabindex="0"><thead><tr><th>文档</th><th>说明</th></tr></thead><tbody><tr><td><a href="/kb-docs/zh/quick-start/create-first-site.html">创建第一个站点</a></td><td>从模板、空白、导入或克隆开始</td></tr><tr><td><a href="/kb-docs/zh/cms/site/pages.html">CMS：站点页面</a></td><td>创建站点后维护页面</td></tr><tr><td><a href="/kb-docs/zh/cms/development/">CMS：开发</a></td><td>维护布局、视图、脚本、样式、Code 等资源</td></tr><tr><td><a href="/kb-docs/zh/templateEngine/">模板引擎</a></td><td>理解模板资源如何组织</td></tr></tbody></table>',14))])}const u=e(h,[["render",g]]);export{m as __pageData,u as default};
